    var slug = slugifySegment(stem || 'pr_rework') || 'dev-write';
    return SESSION_GROUP_MAP[slug] || slug;
}

function padHex8(num) {
    var hex = (num >>> 0).toString(16);
    while (hex.length < 8) hex = '0' + hex;
