        throw policyError('reviewPolicy.identity must be an object (gh-1332 knobs)');
    }
    return {
        preset: preset,
        source: source || 'built-in default',
        severities: severityTableFor(preset, raw.severities),
        bounds: boundsOrDefault(raw),
        identity: raw.identity || {}
    };
